12	// 本文件为装载功能补充并发回归保障：同一件货物被两份各自合法的调整同时
13	// 安排到不同舱位、且两次正式提交使用不同调整编号时，登记处在并发调用下
14	// 仍必须保证只有一份安排整体生效——
15	//   - 恰好一次成功，另一份返回状态不符错误 ErrStateMismatch；
16	//   - 失败错误指向被抢先装载的货物 G1，携带失败调整自己的编号，中文说明
17	//     能让调用方知道 G1 已经装载在哪一个舱位，且失败不返回成功变化记录；
18	//   - 成功结果中的货物去向、舱位重量变化与最终实际配载完全一致；
19	//   - 整份调整一起生效：失败安排中的另一件货物不得留下已装载状态或重量；
20	//   - 货物查询给出的所属舱位与舱位清单一致，三件货物的登记资料保持原样。
21	//
22	// 两份安排单独提交都符合承重与混装规则，因此并发下的拒绝只能来自
23	// G1 已被另一份安排装载，而不是其他资料错误。首尾空白按现有编号规则
24	// 去掉后，“ G1 ”与“G1”仍指同一件货物，上述保障不变。
25	
26	// contestPlan 描述一份竞争中的装载安排：把 G1 与另一件货物装入同一舱位。
27	type contestPlan struct {
28		name        string // 安排名称，用于判定哪一份生效
29		adjID       string // 提交时使用的调整编号（可能带首尾空白）
30		g1Ref       string // 安排中 G1 的写法（可能带首尾空白）
31		otherCargo  string // 同一份安排中的另一件货物
32		winComp     string // 目标舱位，也是该安排生效后 G1 所在舱位
33		totalWeight int64  // 该安排生效后目标舱位的已用重量
34	}
35	
36	// contestOutcome 记录一份安排的提交结果。
37	type contestOutcome struct {
38		plan contestPlan
39		res  *AdjustmentResult
40		err  error
41	}
42	
43	// 两份安排：A 把 G1、G2 装入 C1（50 千克）；B 把 G1、G3 装入 C2
44	// （70 千克）。三件货物同目的地且 C1、C2 承重均为 100 千克，每份安排
45	// 单独看都满足承重与混装规则。
46	func contestPlans(g1RefA, g1RefB, idA, idB string) (contestPlan, contestPlan) {
47		planA := contestPlan{
48			name:        "A",
49			adjID:       idA,
50			g1Ref:       g1RefA,
51			otherCargo:  "G2",
52			winComp:     "C1",
53			totalWeight: 50,
54		}
55		planB := contestPlan{
56			name:        "B",
57			adjID:       idB,
58			g1Ref:       g1RefB,
59			otherCargo:  "G3",
60			winComp:     "C2",
61			totalWeight: 70,
62		}
63		return planA, planB
64	}
65	
66	// newConcurrentContestRegistry 登记两个空舱位 C1、C2（承重均 100 千克）
67	// 与三件同目的地、均不允许混装的未装载货物 G1(30)、G2(20)、G3(40)。
68	func newConcurrentContestRegistry(t *testing.T) *Registry {
69		t.Helper()
70		r := NewRegistry()
71		mustRegisterCompartment(t, r, "C1", 100)
72		mustRegisterCompartment(t, r, "C2", 100)
73		mustRegisterCargo(t, r, "G1", 30, "东港", false)
74		mustRegisterCargo(t, r, "G2", 20, "东港", false)
75		mustRegisterCargo(t, r, "G3", 40, "东港", false)
76		return r
77	}
78	
79	// contestOps 按安排中各编号的原始写法（可能含首尾空白）构造装载操作。
80	func contestOps(p contestPlan) []Op {
81		return []Op{
82			{Kind: OpLoad, CargoID: p.otherCargo, Target: p.winComp},
83			{Kind: OpLoad, CargoID: p.g1Ref, Target: " " + p.winComp + " "},
84		}
85	}
86	
87	// runContestRound 在同一个登记处上让两份安排在同一道起跑线后并发提交。
88	// delayA/delayB > 0 时，对应安排在开闸后先等待该时长再提交，用于在多轮
89	// 中覆盖两种生效先后；两者均为 0 时是纯粹的同时竞争。返回生效安排名称。
90	func runContestRound(t *testing.T, planA, planB contestPlan, delayA, delayB time.Duration) string {
91		t.Helper()
92		r := newConcurrentContestRegistry(t)
93	
94		start := make(chan struct{})
95		outcomes := make(chan contestOutcome, 2)
96		var wg sync.WaitGroup
97		submit := func(p contestPlan, delay time.Duration) {
98			defer wg.Done()
99			<-start
100			if delay > 0 {
101				time.Sleep(delay)
102			}
103			res, err := r.Adjust(p.adjID, contestOps(p))
104			outcomes <- contestOutcome{plan: p, res: res, err: err}
105		}
106		wg.Add(2)
107		go submit(planA, delayA)
108		go submit(planB, delayB)
109		close(start)
110		wg.Wait()
111		close(outcomes)
112	
113		var winner, loser *contestOutcome
114		for o := range outcomes {
115			o := o
116			if o.err == nil {
117				if winner != nil {
118					t.Fatalf("两份安排都成功：%s 与 %s 都返回了成功结果，G1 被重复装载",
119						winner.plan.name, o.plan.name)
120				}
121				winner = &o
122			} else {
123				if loser != nil {
124					t.Fatalf("两份安排都失败：%s 返回 %v，%s 返回 %v，应有恰好一次成功",
125						loser.plan.name, loser.err, o.plan.name, o.err)
126				}
127				loser = &o
128			}
129		}
130		if winner == nil || loser == nil {
131			t.Fatalf("并发提交结束后成功/失败数量异常: winner=%v loser=%v", winner, loser)
132		}
133	
134		assertLoserStateMismatch(t, *loser, winner.plan)
135		assertWinnerResult(t, *winner)
136		assertContestFinalStowage(t, r, winner.plan, loser.plan)
137		assertContestRegistrationsUnchanged(t, r)
138		return winner.plan.name
139	}
140	
141	// assertLoserStateMismatch 核对失败安排：错误是携带调整编号的 *Error，
142	// 原因为状态不符、对象为 G1、编号属于失败安排自己，中文说明指出 G1 已在
143	// 胜出安排的舱位中，且失败不返回成功变化记录。
144	func assertLoserStateMismatch(t *testing.T, loser contestOutcome, winning contestPlan) {
145		t.Helper()
146		if loser.res != nil {
147			t.Fatalf("失败安排 %s 不应返回成功变化记录: %+v", loser.plan.name, loser.res)
148		}
149		var se *Error
150		if !errors.As(loser.err, &se) {
151			t.Fatalf("安排 %s 应返回 *Error，实际为 %T: %v", loser.plan.name, loser.err, loser.err)
152		}
153		if se.Kind != ErrStateMismatch {
154			t.Fatalf("安排 %s 应因 G1 已被另一份安排装载而报状态不符，实际为 %s（%v）",
155				loser.plan.name, se.Kind, loser.err)
156		}
157		if se.ID != "G1" {
158			t.Fatalf("失败错误应指向 G1，实际 ID=%q", se.ID)
159		}
160		wantAID := strings.TrimSpace(loser.plan.adjID)
161		if se.AdjustmentID != wantAID {
162			t.Fatalf("失败错误应携带失败安排自己的编号 %q，实际 %q", wantAID, se.AdjustmentID)
163		}
164		msg := se.Error()
165		if !strings.Contains(msg, "G1") {
166			t.Fatalf("失败说明应指出货物 G1: %s", msg)
167		}
168		if !strings.Contains(msg, winning.winComp) {
169			t.Fatalf("失败说明应让调用方知道 G1 已装载在舱位 %s: %s", winning.winComp, msg)
170		}
171		if !strings.Contains(msg, "已装载") {
172			t.Fatalf("失败说明应表明 G1 已经装载: %s", msg)
173		}
174	}
175	
176	// assertWinnerResult 核对成功结果中的货物去向与舱位重量变化与该安排一致。
177	func assertWinnerResult(t *testing.T, winner contestOutcome) {
178		t.Helper()
179		p := winner.plan
180		if winner.res == nil {
181			t.Fatalf("生效安排 %s 应返回成功结果", p.name)
182		}
183		if winner.res.ID != strings.TrimSpace(p.adjID) {
184			t.Fatalf("成功结果编号应为去空白后的 %q，实际 %q",
185				strings.TrimSpace(p.adjID), winner.res.ID)
186		}
187		wantCargoChanges := []CargoChange{
188			{CargoID: "G1", From: "", To: p.winComp},
189			{CargoID: p.otherCargo, From: "", To: p.winComp},
190		}
191		if !reflect.DeepEqual(winner.res.CargoChanges, wantCargoChanges) {
192			t.Fatalf("安排 %s 成功的货物变化应为 %+v，实际 %+v",
193				p.name, wantCargoChanges, winner.res.CargoChanges)
194		}
195		wantCompChanges := []CompartmentChange{
196			{CompartmentID: p.winComp, WeightBefore: 0, WeightAfter: p.totalWeight},
197		}
198		if !reflect.DeepEqual(winner.res.CompartmentChanges, wantCompChanges) {
199			t.Fatalf("安排 %s 成功的舱位重量变化应为 %+v，实际 %+v",
200				p.name, wantCompChanges, winner.res.CompartmentChanges)
201		}
202	}
203	
204	// assertContestFinalStowage 按实际生效的安排核对最终配载：胜出舱位只有
205	// G1 与该安排的另一件货物、重量正确；另一份安排的目标舱位仍为空；
206	// 货物查询与舱位清单逐一对应；失败安排中的另一件货物保持未装载、不占重量。
207	func assertContestFinalStowage(t *testing.T, r *Registry, winning, losing contestPlan) {
208		t.Helper()
209		winView, err := r.Compartment(winning.winComp)
210		if err != nil {
211			t.Fatalf("查询胜出舱位 %s 失败: %v", winning.winComp, err)
212		}
213		wantIDs := []string{"G1", winning.otherCargo}
214		if got := cargoIDs(*winView); !reflect.DeepEqual(got, wantIDs) {
215			t.Fatalf("安排 %s 生效后 %s 应只有 %v，实际 %v",
216				winning.name, winning.winComp, wantIDs, got)
217		}
218		if winView.MaxWeight != 100 ||
219			winView.UsedWeight != winning.totalWeight ||
220			winView.RemainingWeight != 100-winning.totalWeight {
221			t.Fatalf("安排 %s 生效后 %s 重量应为已用 %d/剩余 %d，实际 %+v",
222				winning.name, winning.winComp,
223				winning.totalWeight, 100-winning.totalWeight, winView)
224		}
225	
226		// 失败安排的目标舱位仍为空：其另一件货物不得留下已装载状态或占用重量。
227		loseView, err := r.Compartment(losing.winComp)
228		if err != nil {
229			t.Fatalf("查询失败安排目标舱位 %s 失败: %v", losing.winComp, err)
230		}
231		if loseView.MaxWeight != 100 || loseView.UsedWeight != 0 ||
232			loseView.RemainingWeight != 100 || len(loseView.Cargo) != 0 {
233			t.Fatalf("安排 %s 失败后 %s 应仍为空舱，实际 %+v",
234				losing.name, losing.winComp, loseView)
235		}
236	
237		// 货物查询给出的所属舱位必须与舱位清单一致。
238		g1, _ := r.Cargo("G1")
239		if !g1.Loaded || g1.CompartmentID != winning.winComp {
240			t.Fatalf("G1 应由生效安排 %s 装入 %s，实际 %+v",
241				winning.name, winning.winComp, g1)
242		}
243		other, _ := r.Cargo(winning.otherCargo)
244		if !other.Loaded || other.CompartmentID != winning.winComp {
245			t.Fatalf("%s 应随生效安排在 %s，实际 %+v",
246				winning.otherCargo, winning.winComp, other)
247		}
248		leftOut, _ := r.Cargo(losing.otherCargo)
249		if leftOut.Loaded || leftOut.CompartmentID != "" {
250			t.Fatalf("失败安排中的 %s 应仍未装载、不占重量，实际 %+v",
251				losing.otherCargo, leftOut)
252		}
253	}
254	
255	// assertContestRegistrationsUnchanged 确认三件货物的登记资料（重量、
256	// 目的地、混装许可）在并发提交后保持原样。
257	func assertContestRegistrationsUnchanged(t *testing.T, r *Registry) {
258		t.Helper()
259		want := map[string]struct {
260			weight int64
261			dest   string
262		}{
263			"G1": {30, "东港"},
264			"G2": {20, "东港"},
265			"G3": {40, "东港"},
266		}
267		for id, w := range want {
268			c, err := r.Cargo(id)
269			if err != nil {
270				t.Fatalf("查询货物 %s 失败: %v", id, err)
271			}
272			if c.Weight != w.weight || c.Destination != w.dest || c.AllowMixed {
273				t.Fatalf("货物 %s 的登记资料被改动: %+v（应保持 %d 千克、%s、不允许混装）",
274					id, c, w.weight, w.dest)
275			}
276		}
277	}
278	
279	// TestConcurrentAdjustSameCargoOnlyOneCommitTakesEffect 是核心并发回归：
280	// 两份各自合法、编号不同的安排并发抢装同一件 G1，多轮竞争中必须恰好有
281	// 一份生效，且两种生效先后都实际出现过（不规定哪份成功），无论哪份成功，
282	// 成功结果、失败错误与最终配载都满足各自的要求。
283	func TestConcurrentAdjustSameCargoOnlyOneCommitTakesEffect(t *testing.T) {
284		cases := []struct {
285			name     string
286			g1RefA   string
287			g1RefB   string
288			adjIDInA string
289			adjIDInB string
290		}{
291			{
292				name:     "两份安排都写作G1",
293				g1RefA:   "G1",
294				g1RefB:   "G1",
295				adjIDInA: "adj-to-c1",
296				adjIDInB: "adj-to-c2",
297			},
298			{
299				name:     "一份写作带首尾空白的G1",
300				g1RefA:   " G1 ",
301				g1RefB:   "G1",
302				adjIDInA: "  adj-to-c1  ",
303				adjIDInB: " adj-to-c2 ",
304			},
305		}
306	
307		for _, tc := range cases {
308			t.Run(tc.name, func(t *testing.T) {
309				planA, planB := contestPlans(tc.g1RefA, tc.g1RefB, tc.adjIDInA, tc.adjIDInB)
310	
311				// 前置事实：两份安排各自单独提交都合法，并发下的拒绝只能来自
312				// G1 已被另一份安排装载，而不是承重、混装或编号等资料错误。
313				t.Run("每份安排单独提交都合法", func(t *testing.T) {
314					rA := newConcurrentContestRegistry(t)
315					resA, err := rA.Adjust(planA.adjID, contestOps(planA))
316					if err != nil {
317						t.Fatalf("安排 A 单独提交本应合法: %v", err)
318					}
319					assertWinnerResult(t, contestOutcome{plan: planA, res: resA})
320					assertContestFinalStowage(t, rA, planA, planB)
321					assertContestRegistrationsUnchanged(t, rA)
322	
323					rB := newConcurrentContestRegistry(t)
324					resB, err := rB.Adjust(planB.adjID, contestOps(planB))
325					if err != nil {
326						t.Fatalf("安排 B 单独提交本应合法: %v", err)
327					}
328					assertWinnerResult(t, contestOutcome{plan: planB, res: resB})
329					assertContestFinalStowage(t, rB, planB, planA)
330					assertContestRegistrationsUnchanged(t, rB)
331				})
332	
333				// 并发竞争：多轮覆盖两种先后，并穿插不偏不倚的同时竞争。
334				wins := map[string]int{"A": 0, "B": 0}
335				const rounds = 40
336				for i := 0; i < rounds; i++ {
337					var delayA, delayB time.Duration
338					switch i % 4 {
339					case 0:
340						delayB = 2 * time.Millisecond // 偏向安排 A 先提交
341					case 1:
342						delayA = 2 * time.Millisecond // 偏向安排 B 先提交
343					case 2:
344						delayB = 5 * time.Millisecond // 再次偏向 A，加大先后差
345					default:
346						// 两份安排零等待同时开抢，纯粹的锁竞争。
347					}
348					wins[runContestRound(t, planA, planB, delayA, delayB)]++
349				}
350	
351				// 极端调度下若某种先后始终未出现，补几轮强偏向竞争；仍不出现
352				// 才判定失败。两种生效先后都必须被实际观察到（不规定哪份成功，
353				// 但任一份都应能在并发提交中正常生效）。
354				forceMissing := func(missing string, planMissing, planOther contestPlan) {
355					for j := 0; j < 3 && wins[missing] == 0; j++ {
356						if missing == "A" {
357							wins[runContestRound(t, planMissing, planOther, 0, 25*time.Millisecond)]++
358						} else {
359							wins[runContestRound(t, planMissing, planOther, 25*time.Millisecond, 0)]++
360						}
361					}
362				}
363				if wins["A"] == 0 {
364					forceMissing("A", planA, planB)
365				}
366				if wins["B"] == 0 {
367					forceMissing("B", planA, planB)
368				}
369				if wins["A"] == 0 || wins["B"] == 0 {
370					t.Fatalf("经过 %d 轮并发提交仍只观察到一种生效先后（A 胜 %d 次、B 胜 %d 次），"+
371						"两种先后都应被接受", rounds, wins["A"], wins["B"])
372				}
373				t.Logf("并发竞争 %d 轮：安排 A 生效 %d 次，安排 B 生效 %d 次",
374					rounds, wins["A"], wins["B"])
375			})
376		}
377	}
378

