func TestAdjustmentResultSnapshotIndependent(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", 10, "X", true); err != nil {
		t.Fatal(err)
	}
	res, err := r.Adjust("A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
	if err != nil {
		t.Fatal(err)
	}
	// 调用方修改返回结果。
	res.CargoChanges[0].CargoID = "HACKED"
	res.CompartmentChanges[0].WeightAfter = 9999

	// 以相同编号重复提交，返回的首次结果未被污染。
	res2, err := r.Adjust("A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
	if err != nil {
		t.Fatal(err)
	}
	if res2.CargoChanges[0].CargoID != "G1" {
		t.Fatalf("已保存的调整结果不应被调用方修改: %+v", res2.CargoChanges[0])
	}
	if res2.CompartmentChanges[0].WeightAfter != 10 {
		t.Fatalf("已保存的调整结果不应被调用方修改: %+v", res2.CompartmentChanges[0])
	}
}

// ---------- 其他边界 ----------

func TestUnknownOpKind(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", 10, "X", true); err != nil {
		t.Fatal(err)
	}
	se := requireError(t, func() error {
		_, err := r.Adjust("A1", []Op{{Kind: OpKind(99), CargoID: "G1", Target: "C1"}})
		return err
	}(), ErrInvalidOp)
	if se.ID != "G1" {
		t.Fatalf("无效操作种类应指出货物，实际 ID=%q", se.ID)
	}
}

func TestMoveCargoIntoSameDestinationMixedCompartment(t *testing.T) {
	// 综合场景：移动后目标舱室混装合法、原舱室重量收回。
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCompartment("C2", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", 30, "Shanghai", false); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G2", 20, "Shanghai", false); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Adjust("A1", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G2", Target: "C2"},
	}); err != nil {
		t.Fatal(err)
	}
	// G1 与 G2 目的地相同，移动 G1 到 C2 合法。
	if _, err := r.Adjust("A2", []Op{{Kind: OpMove, CargoID: "G1", Target: "C2"}}); err != nil {
		t.Fatalf("相同目的地混装应合法: %v", err)
	}
	cpt1, _ := r.Compartment("C1")
	cpt2, _ := r.Compartment("C2")
	if cpt1.UsedWeight != 0 || cpt2.UsedWeight != 50 {
		t.Fatalf("舱位重量错误: %+v %+v", cpt1, cpt2)
	}
}

package stowage

import "fmt"

// ErrorKind 描述一次配载操作失败的具体原因。
type ErrorKind int

const (
	// ErrOK 表示没有错误（内部使用）。
	ErrOK ErrorKind = iota
	// ErrInvalidID 编号去掉首尾空白后为空。
	ErrInvalidID
	// ErrInvalidWeight 重量或最大承重不是正整数。
	ErrInvalidWeight
	// ErrInvalidDestination 目的地去掉首尾空白后为空。
	ErrInvalidDestination
	// ErrInvalidOp 操作种类无法识别。
	ErrInvalidOp
	// ErrAlreadyExists 登记对象已存在。
	ErrAlreadyExists
	// ErrNotFound 涉及的货物或舱位不存在。
	ErrNotFound
	// ErrStateMismatch 货物状态与操作不符（未装载或已装载）。
	ErrStateMismatch
	// ErrDuplicateOp 同一调整中货物重复出现，或移动到原舱位。
	ErrDuplicateOp
	// ErrEmptyAdjustment 调整不包含任何操作。
	ErrEmptyAdjustment
	// ErrOverweight 舱位总重量超过最大承重。
	ErrOverweight
	// ErrMixedLoading 不同目的地货物混装，但有货物不允许混装。
	ErrMixedLoading
	// ErrOverflow 重量合计超过 int64 可表示范围。
	ErrOverflow
	// ErrAdjustmentIDConflict 调整编号已用于不同内容。
	ErrAdjustmentIDConflict
)

// String 返回错误原因的中文说明。
func (k ErrorKind) String() string {
	switch k {
	case ErrInvalidID:
		return "编号为空"
	case ErrInvalidWeight:
		return "重量或承重非正整数"
	case ErrInvalidDestination:
		return "目的地为空"
	case ErrInvalidOp:
		return "操作种类无效"
	case ErrAlreadyExists:
		return "对象已存在"
	case ErrNotFound:
		return "对象不存在"
	case ErrStateMismatch:
		return "状态不符"
	case ErrDuplicateOp:
		return "重复操作"
	case ErrEmptyAdjustment:
		return "调整为空"
	case ErrOverweight:
		return "超重"
	case ErrMixedLoading:
		return "混装冲突"
	case ErrOverflow:
		return "重量溢出"
	case ErrAdjustmentIDConflict:
		return "调整编号冲突"
	default:
		return "未知错误"
	}
}

// Error 是配载操作的结构化失败结果，指出涉及的对象与具体原因。
type Error struct {
	Kind         ErrorKind
	ID           string // 涉及的货物或舱位编号，可能为空
	AdjustmentID string // 涉及的调整编号，可能为空
	detail       string
}

func (e *Error) Error() string {
	if e.detail != "" {
		return e.detail
	}
	return e.Kind.String()
}

// fail 构造一个带说明的结构化错误。
func fail(kind ErrorKind, id string, format string, args ...any) *Error {
	return &Error{Kind: kind, ID: id, detail: fmt.Sprintf(format, args...)}
}

// rejectionError 把最终配载评估出的单个拒绝原因转换成正式操作的结构化
// 错误，Adjust 与 AmendCargo 共用同一套对应关系，保证同一种拒绝原因的
// 错误类别、涉及对象与中文说明一致：
// 重量溢出与超重指向舱位，超重说明保留预计总重量与最大承重，溢出不展示
// 无法表示的合计重量；混装冲突指向舱内编号字典序最靠前的一件不允许
// 混装货物（可能原本就在舱内），说明同时指出舱位与该货物。
// failf 决定错误是否携带调整编号：Adjust 传入盖编号的构造函数，
// AmendCargo 直接传入 fail。
func rejectionError(
	rej *Rejection,
	failf func(kind ErrorKind, id string, format string, args ...any) *Error,
) *Error {
	switch rej.Kind {
	case ErrOverflow:
		return failf(ErrOverflow, rej.CompartmentID, "舱位 %s 重量合计超过 int64 可表示范围", rej.CompartmentID)
	case ErrOverweight:
		return failf(ErrOverweight, rej.CompartmentID,
			"舱位 %s 总重量 %d 千克超过最大承重 %d 千克",
			rej.CompartmentID, rej.UsedWeight, rej.MaxWeight)
	default:
		return failf(ErrMixedLoading, rej.firstOffender(),
			"舱位 %s 存在不同目的地货物，但货物 %s 不允许混装",
			rej.CompartmentID, rej.firstOffender())
	}
}

